input.command:
# Extract user queries + short assistant summaries from today's transcripts
BASE=/Users/mac/.cursor/projects/Users-mac-Desktop-CHcode/agent-transcripts
for d in fb151a30-964b-4d88-9140-c49a8b68e9a3 40485fc1-c77a-4013-9b30-49f0fb75ca04 6cba46ed-180b-470d-a1de-00cd0ccb3536 4563e872-4452-440c-86a2-a062729b1281 66ab9aff-945e-4524-abb2-340e2bf125b0 ed7cd1a6-2c4a-4912-ae29-e57b7f82daa0; do
  f="$BASE/$d/$d.jsonl"
  echo "======== $d ========"
  python3 - <<PY
import json
from pathlib import Path
p=Path("$f")
if not p.exists():
  print("missing"); raise SystemExit
for i,line in enumerate(p.open()):
  try: o=json.loads(line)
  except: continue
  role=o.get("role") or o.get("type") or ""
  # various formats
  content=o.get("content") or o.get("message") or o.get("text")
  if isinstance(content,list):
    texts=[]
    for c in content:
      if isinstance(c,dict):
        if c.get("type") in ("text","input_text","output_text") or "text" in c:
          texts.append(str(c.get("text") or "")[:500])
      elif isinstance(c,str):
        texts.append(c[:500])
    content="\n".join(texts)
  elif isinstance(content,dict):
    content=str(content.get("text") or content)[:800]
  else:
    content=str(content or "")[:800]
  # also try nested message
  if not content or content=="None":
    m=o.get("message") or {}
    if isinstance(m,dict):
      role=m.get("role") or role
      c=m.get("content")
      if isinstance(c,list):
        content=" ".join(str(x.get("text",x) if isinstance(x,dict) else x)[:300] for x in c)
      else:
        content=str(c)[:800]
  if role in ("user","human") or (isinstance(role,str) and "user" in role.lower()):
    # skip system wakes noise partially
    t=content.strip()
    if not t: continue
    if "AGENT_LOOP_WAKE" in t and "DAILY_REPORT" not in t and "整理日报" not in t:
      # show first line only for wakes
      print(f"U[{i}]: {t.splitlines()[0][:200]}")
    else:
      print(f"U[{i}]: {t[:350].replace(chr(10),' / ')}")
  elif role in ("assistant",) and i<5:
    pass
print("--- assistant last-ish lines ---")
# grab last assistant text chunks that look like conclusions
count=0
lines=list(p.open())
for line in reversed(lines[-80:]):
  try: o=json.loads(line)
  except: continue
  m=o.get("message") or o
  role=m.get("role") if isinstance(m,dict) else o.get("role")
  if role!="assistant": continue
  c=m.get("content") if isinstance(m,dict) else o.get("content")
  text=""
  if isinstance(c,list):
    for x in c:
      if isinstance(x,dict) and x.get("type")=="text":
        text+=x.get("text") or ""
  elif isinstance(c,str):
    text=c
  text=text.strip()
  if len(text)<40: continue
  print(f"A: {text[:400].replace(chr(10),' / ')}")
  count+=1
  if count>=2: break
PY
done
